23	const (
24		cellDataAPITimeout = 30 * time.Second
25	
26		jurisdictionIdentityScope = "openid"
27	
28		// clustersAPIPath is entire-core's cluster catalog endpoint.
29		clustersAPIPath = "/api/v1/clusters"
30	)
31	
32	// jurisdictionLabelPattern bounds a home_jurisdiction claim to a single DNS
33	// label before it is substituted into a URL template. The claim rides on the
34	// login JWT (which we decode without verifying the signature) and, for the
35	// home-jurisdiction fallback path, is attacker-influenceable if a token is ever
36	// mis-minted; constraining it to [a-z0-9-] means it can only ever name a
37	// sibling jurisdiction, never inject host/scheme syntax (e.g.
38	// "us.auth.evil.tld") into jurisdictionAudience / jurisdictionCoreURL.
39	var jurisdictionLabelPattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)
40	
41	// CellTarget pins the entire-api cell a repo-scoped call must reach and the
42	// jurisdiction its identity token must be minted for. The cli layer resolves it
43	// from the repo's own cluster (via coreapi mirrors/clusters), so a repo-scoped
44	// route reaches the cell that HOSTS the repo — not the caller's home cell. A nil
45	// target falls back to home-jurisdiction routing (derived from the login JWT),
46	// which is correct for the common same-region case and for local dev.
47	type CellTarget struct {
48		// BaseURL is the cell's apiUrl to dial (e.g. https://aws-eu-west-1.api.entire.io).
49		BaseURL string
50		// Jurisdiction is the repo's cluster jurisdiction; it drives the identity
51		// token's audience and the core the exchange is performed at.
52		Jurisdiction string
53	}
54	
55	// resolveContextForCellAPI is the discovery seam for cell routing, swapped in
56	// tests. Mirrors resolveContextForAPI.
57	var resolveContextForCellAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI
58	
59	// SetResolveContextForCellAPIForTest overrides the cell-API discovery seam.
60	func SetResolveContextForCellAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
61		t.Helper()
62		prev := resolveContextForCellAPI
63		resolveContextForCellAPI = fn
64		return func() { resolveContextForCellAPI = prev }
65	}
