177	// targetJurisdiction picks the jurisdiction to mint for: the explicit repo
178	// target when present, otherwise the caller's home jurisdiction from the login
179	// JWT. The result is validated as a DNS label before it is templated into URLs.
180	func targetJurisdiction(target *CellTarget, loginJWT string) (string, error) {
181		jurisdiction := ""
182		if target != nil {
183			jurisdiction = strings.TrimSpace(target.Jurisdiction)
184		}
185		if jurisdiction == "" {
186			var err error
187			jurisdiction, err = homeJurisdictionFromLoginJWT(loginJWT)
188			if err != nil {
189				return "", err
190			}
191		}
192		if jurisdiction == "" {
193			return "", errors.New("login token has no home_jurisdiction claim; cannot route to entire-api cell")
194		}
195		if !jurisdictionLabelPattern.MatchString(jurisdiction) {
196			return "", fmt.Errorf("jurisdiction %q is not a valid label; refusing to route", jurisdiction)
197		}
198		return jurisdiction, nil
199	}
200	
201	// resolveTargetCellBaseURL decides which cell origin to dial. See
202	// NewEntireAPICellClient's precedence doc.
203	func resolveTargetCellBaseURL(ctx context.Context, target *CellTarget, dataOrigin, jurisdiction, coreURL, loginJWT string, httpClient *http.Client) (string, error) {
204		if target != nil && strings.TrimSpace(target.BaseURL) != "" {
205			return strings.TrimRight(target.BaseURL, "/"), nil
206		}
207		if !isBFFOrigin(dataOrigin) {
208			// Already a cell URL, or a loopback local-dev host: keep it verbatim.
209			return strings.TrimRight(dataOrigin, "/"), nil
210		}
211		return resolveCellAPIBaseURL(ctx, coreURL, loginJWT, jurisdiction, httpClient)
212	}
213	
214	// isBFFOrigin reports whether origin is a BFF / apex host that fronts multiple
215	// cells (so the actual cell must be resolved from the cluster catalog), as
216	// opposed to a direct entire-api cell (host contains ".api.") or a loopback
217	// local-dev host (kept verbatim). This is environment-agnostic: it recognises
218	// prod (entire.io), staging (partial.to) and any future apex without a
219	// hardcoded domain list.
220	func isBFFOrigin(origin string) bool {
221		u, err := url.Parse(origin)
222		if err != nil || u.Host == "" {
223			return false
224		}
225		host := strings.ToLower(u.Hostname())
226		if host == "" || isLoopbackHost(host) {
227			return false
228		}
229		// A direct cell advertises itself under an ".api." label; anything else that
230		// isn't loopback is treated as a BFF/apex needing cell resolution.
231		return !strings.Contains(host, ".api.")
232	}
233	
234	func isLoopbackHost(host string) bool {
235		switch host {
236		case "localhost", "127.0.0.1", "::1":
237			return true
238		}
239		return false
240	}
241	
242	// entireDomainFamily returns the registrable apex ("entire.io" / "partial.to")
243	// derived from the discovered login core's host, or "" for loopback/custom
244	// cores. It lets the audience/core templates follow the environment the user is
245	// actually logged into (prod vs staging) instead of a hardcoded prod default.
246	func entireDomainFamily(coreURL string) string {
247		u, err := url.Parse(coreURL)
248		if err != nil {
249			return ""
250		}
251		host := strings.ToLower(u.Hostname())
252		switch {
253		case host == "partial.to" || strings.HasSuffix(host, ".partial.to"):
254			return "partial.to"
255		case host == "entire.io" || strings.HasSuffix(host, ".entire.io"):
256			return "entire.io"
257		default:
258			return ""
259		}
260	}
261	
262	// environmentFamily picks the registrable apex to template jurisdiction URLs
263	// against. The configured data host (what the user pointed the CLI at) is the
264	// most reliable signal for prod-vs-staging, so it wins; the discovered login
265	// core is the fallback.
266	func environmentFamily(dataOrigin, discoveredCore string) string {
267		if fam := entireDomainFamily(dataOrigin); fam != "" {
268			return fam
269		}
270		return entireDomainFamily(discoveredCore)
271	}
272	
273	// jurisdictionAudience returns the aud the entire-api cell for `jurisdiction`
274	// pins its identity tokens to (its jurisdiction host). Precedence:
275	//   - ENTIRE_API_AUDIENCE_TEMPLATE (with {jurisdiction}) if set;
276	//   - else https://{jurisdiction}.<family> for the environment family;
277	//   - else (loopback/custom) the data origin, best-effort and overridable.
278	//
279	// This mirrors the BFF's buildAudience(template, jurisdiction) (repos-stream.ts).
280	func jurisdictionAudience(jurisdiction, dataOrigin, discoveredCore string) string {
281		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_API_AUDIENCE_TEMPLATE")); tmpl != "" {
282			return applyJurisdictionTemplate(tmpl, jurisdiction)
283		}
284		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
285			return "https://" + jurisdiction + "." + fam
286		}
287		return strings.TrimRight(dataOrigin, "/")
288	}
289	
290	// jurisdictionCoreURL returns the entire-core origin the identity-token exchange
291	// is performed at for `jurisdiction`. Precedence:
292	//   - a loopback discovered core (local dev): honour it verbatim — the local
293	//     core signs the local login JWT, and the prod template would send the
294	//     exchange to production, which rejects the local token;
295	//   - ENTIRE_CORE_BASE_URL_TEMPLATE (with {jurisdiction}) if set;
296	//   - else https://{jurisdiction}.auth.<family> for the environment family;
297	//   - else the discovered core verbatim.
298	//
299	// This mirrors the BFF's buildCoreBaseUrl(template, jurisdiction, fallback),
300	// which honours a fallback core when the template can't produce one.
301	func jurisdictionCoreURL(jurisdiction, dataOrigin, discoveredCore string) string {
302		if isLoopbackHTTP(discoveredCore) {
303			return strings.TrimRight(discoveredCore, "/")
304		}
305		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_CORE_BASE_URL_TEMPLATE")); tmpl != "" {
306			// Apply unconditionally: applyJurisdictionTemplate is a no-op when the
307			// template has no {jurisdiction}, yielding the fixed core verbatim — the
308			// single-core case, matching the BFF's buildCoreBaseUrl and this file's
309			// own audience handling.
310			return applyJurisdictionTemplate(tmpl, jurisdiction)
311		}
312		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
313			return "https://" + jurisdiction + ".auth." + fam
314		}
315		return strings.TrimRight(discoveredCore, "/")
316	}
317	
318	func applyJurisdictionTemplate(tmpl, jurisdiction string) string {
319		return strings.ReplaceAll(strings.TrimRight(tmpl, "/"), "{jurisdiction}", jurisdiction)
320	}
321	
322	// requireSafeExchangeURL rejects a target the login JWT / identity token would
323	// be sent to unless it is https (or an explicitly-allowed loopback/insecure
324	// http). It affirmatively requires the https scheme — not merely "not http" —
325	// so ftp/ws/scheme-relative/empty targets from a buggy core catalog can't
326	// smuggle the login JWT off https. Mirrors the tokenmanager guard the sibling
327	// data_api.go relies on.
328	func requireSafeExchangeURL(label, raw string) error {
329		if insecureHTTPEnabled() || isLoopbackHTTP(raw) {
330			return nil
331		}
332		u, err := url.Parse(raw)
333		if err != nil {
334			return fmt.Errorf("%s URL check: parse %q: %w", label, raw, err)
335		}
336		if u.Scheme != "https" || u.Host == "" {
337			return fmt.Errorf("%s URL %q must be https", label, raw)
338		}
339		return nil
340	}
341	
342	func homeJurisdictionFromLoginJWT(loginJWT string) (string, error) {
343		parts := strings.Split(loginJWT, ".")
344		if len(parts) < 2 {
345			return "", errors.New("login token is not a JWT")
346		}
347		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
348		if err != nil {
349			return "", fmt.Errorf("decode login token payload: %w", err)
350		}
351		var claims struct {
352			HomeJurisdiction string `json:"home_jurisdiction"`
353		}
354		if err := json.Unmarshal(payload, &claims); err != nil {
355			return "", fmt.Errorf("parse login token payload: %w", err)
356		}
357		return claims.HomeJurisdiction, nil
358	}
