100	// by every authenticated command for local development.
101	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
102		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
103		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
104			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
105		}
106	}
