109		cmd := &cobra.Command{
110			Use:   "auth",
111			Short: "Manage authentication",
112			Long:  "Authentication subcommands. Includes login, logout, status, and login-context management (contexts, use).",
113			RunE: func(cmd *cobra.Command, _ []string) error {
