127	// --- token ------------------------------------------------------------------
128	
129	// newAuthTokenCmd prints the active control-plane bearer to stdout for
130	// scripting. The user-facing Long and Example carry the detail and the
131	// "treat the output as a secret" caveat; the token resolves the same way the
132	// API client's does (ENTIRE_TOKEN verbatim when set, otherwise the active
133	// context's login JWT, refreshed if it's near expiry), and only the token is
134	// printed — errors and the not-logged-in hint go to stderr so command
135	// substitution stays clean.
136	func newAuthTokenCmd() *cobra.Command {
137		var insecureHTTPAuth bool
138		cmd := &cobra.Command{
139			Use:   "token",
140			Short: "Print the active control-plane bearer token — a live credential, treat as a secret",
141			Long: "Print the active control-plane bearer token to stdout so scripts and\n" +
142				"ad-hoc curl can authenticate against the control-plane API.\n\n" +
143				"The output is a live credential — treat it as a secret. It is the same\n" +
144				"bearer the API client uses: ENTIRE_TOKEN verbatim when set, otherwise the\n" +
145				"active context's login JWT (refreshed if it's near expiry). Only the token\n" +
146				"is printed to stdout; errors and the not-logged-in hint go to stderr so\n" +
147				"command substitution stays clean.",
148			Example: "  curl -H \"Authorization: Bearer $(entire auth token)\" \"https://us.console.entire.io/api/v1/clusters\"",
149			Args:    cobra.NoArgs,
150			RunE: func(cmd *cobra.Command, _ []string) error {
151				// Refresh may exchange/refresh over the network; honor the
152				// plain-HTTP opt-in before resolving so local dev cores work.
153				insecure := applyInsecureHTTPAuth(insecureHTTPAuth)
154				target, err := resolveAuthStatusTarget(cmd.Context(), auth.Contexts, auth.RefreshedLoginToken)
155				if err != nil {
156					return err
157				}
158				// Don't mint/print a bearer for an insecure core unless explicitly
159				// opted in — the token would otherwise be usable over plain HTTP.
160				// Mirrors `auth status`.
161				if !insecure && target.coreURL != "" {
162					if err := api.RequireSecureURL(target.coreURL); err != nil {
163						cmd.SilenceUsage = true
164						return fmt.Errorf("login server URL check: %w", err)
165					}
166				}
167				if target.token == "" {
168					cmd.SilenceUsage = true
169					fmt.Fprintln(cmd.ErrOrStderr(), "Not logged in. Run 'entire login' to authenticate.")
170					return NewSilentError(errors.New("not logged in"))
171				}
172				fmt.Fprintln(cmd.OutOrStdout(), target.token)
173				return nil
174			},
175		}
176		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
177		return cmd
178	}
