180	// --- status -----------------------------------------------------------------
181	
182	func newAuthStatusCmd() *cobra.Command {
183		var insecureHTTPAuth bool
184		cmd := &cobra.Command{
185			Use:   "status",
186			Short: "Show authentication status",
187			RunE: func(cmd *cobra.Command, _ []string) error {
188				target, err := resolveAuthStatusTarget(cmd.Context(), auth.Contexts, auth.RefreshedLoginToken)
189				if err != nil {
190					return err
191				}
192				// We send the session token to target.coreURL; enforce TLS on it.
193				if !applyInsecureHTTPAuth(insecureHTTPAuth) && target.coreURL != "" {
194					if err := api.RequireSecureURL(target.coreURL); err != nil {
195						return fmt.Errorf("context login server URL check: %w", err)
196					}
197				}
198				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(), defaultFetchProfile, defaultListAuthSessions, target)
199			},
200		}
201		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
202		return cmd
