236	// statusTarget is the resolved core to act against: the active context's
237	// CoreURL + its session token. Zero coreURL/token means not logged in.
238	// Shared by `auth status` (profile + session list) and `logout`
239	// (revocation) so both hit the same login server.
240	//
241	// envToken marks the target as resolved from ENTIRE_TOKEN rather than a stored
242	// context: the bearer is the env token itself, sent verbatim to its own aud,
243	// and there is no stored session to manage — so status renders it without the
244	// context/keychain/session lines.
245	type statusTarget struct {
246		coreURL       string
247		token         string
248		activeContext string
