253	// resolveAuthStatusTarget picks the target for `entire auth status`, honouring
254	// ENTIRE_TOKEN: when it is set the request dials the token's own aud (exactly
255	// as coreapi.New does), so status must report that core, not a stored context
256	// that the request never touches. `logout` deliberately does NOT use this —
257	// logout manages a stored login session, which an ephemeral env token has none
258	// of, so it stays on resolveStatusTarget (the active context).
259	func resolveAuthStatusTarget(ctx context.Context, listContexts contextsProvider, resolveLogin loginTokenResolver) (statusTarget, error) {
260		if raw, ok := os.LookupEnv(auth.EnvTokenVar); ok {
261			return resolveEnvTokenStatusTarget(raw)
262		}
263		return resolveStatusTarget(ctx, listContexts, resolveLogin)
264	}
265	
266	// resolveEnvTokenStatusTarget builds the status target from ENTIRE_TOKEN via the
267	// shared auth.ParseEnvToken — the same trim/blank/aud validation coreapi.New
268	// applies — so status reports exactly the core a request would dial. The token
269	// is the bearer; fail-closed (a blank or malformed value errors, never falls
270	// back to a stored context).
271	func resolveEnvTokenStatusTarget(raw string) (statusTarget, error) {
272		coreURL, token, err := auth.ParseEnvToken(raw)
273		if err != nil {
274			return statusTarget{}, err //nolint:wrapcheck // auth.ParseEnvToken already prefixes with EnvTokenVar
275		}
276		return statusTarget{coreURL: coreURL, token: token, envToken: true}, nil
277	}
278	
279	// resolveStatusTarget picks the core + token for `entire auth status` (and
280	// `logout`) from the active contexts.json context (so `auth use` retargets
281	// status onto that login server). No active context means not logged in —
282	// the zero-token target renders the `entire login` hint.
283	//
284	// The token is resolved through resolveLogin, which transparently re-mints
285	// an expired login JWT from the stored refresh token: an
286	// expired-but-refreshable session must report "logged in", not "re-login",
287	// and `logout`'s revoke call gets a bearer that still authenticates. When
288	// refresh fails (revoked family, network, opaque token), the raw stored
289	// token is used and the /me liveness probe is the arbiter — preserving the
290	// accurate "no longer valid" outcome for a genuinely dead session.
291	//
292	// A genuine contexts.json read/parse error is surfaced, not swallowed — a
293	// missing file reads as "no contexts" (no error), so an error here means the
294	// file is corrupt or unreadable, which the user must see.
295	func resolveStatusTarget(ctx context.Context, listContexts contextsProvider, resolveLogin loginTokenResolver) (statusTarget, error) {
296		all, current, err := listContexts()
297		if err != nil {
298			return statusTarget{}, fmt.Errorf("load contexts: %w", err)
299		}
300		total := len(all)
301		for _, c := range all {
302			if c.Name != current || c.CoreURL == "" {
303				continue
304			}
305			if tok, terr := resolveLogin(ctx, c); terr == nil && tok != "" {
306				return statusTarget{coreURL: c.CoreURL, token: tok, activeContext: c.Name, totalContexts: total}, nil
307			}
308			if tok, terr := auth.LoginTokenForContext(c); terr == nil && tok != "" {
309				return statusTarget{coreURL: c.CoreURL, token: tok, activeContext: c.Name, totalContexts: total}, nil
310			}
311			// Active context with no readable token: report against its core so
312			// the not-logged-in message names the right login server.
313			return statusTarget{coreURL: c.CoreURL, activeContext: c.Name, totalContexts: total}, nil
314		}
315		return statusTarget{totalContexts: total}, nil
316	}
