318	// defaultFetchProfile fetches a user's profile from coreURL's GET /me with the
319	// given bearer. It doubles as the liveness check for `entire auth status`: a
320	// 401 (or an expired login) means the token is no longer usable, which
321	// isKeychainTokenRejected maps to a re-login hint.
322	func defaultFetchProfile(ctx context.Context, coreURL, token string) (*authProfile, error) {
323		client, err := coreapi.NewWithBearer(coreURL, token)
324		if err != nil {
325			return nil, fmt.Errorf("connect to %s: %w", coreURL, err)
326		}
327		me, err := client.GetMe(ctx)
328		if err != nil {
329			return nil, fmt.Errorf("fetch profile: %w", err)
330		}
331		p := &authProfile{
332			Provider:       me.Auth.Provider,
333			ProviderUserID: me.Auth.ProviderUserId,
334		}
335		p.Handle, _ = me.Global.Handle.Get()
336		p.Jurisdiction, _ = me.Jurisdiction.Get()
337		if reg, ok := me.Regional.Get(); ok {
338			p.DisplayName, _ = reg.DisplayName.Get()
339			p.Email, _ = reg.Email.Get()
340		}
341		return p, nil
342	}
