349	// runAuthStatus reports auth state against the target core: GET /me validates
350	// the token and supplies the profile header, the active login context is shown
351	// locally, and the active sessions (refresh-token families) on that core are
352	// listed so the effect of `logout` / `logout --everywhere` is visible.
353	func runAuthStatus(ctx context.Context, w io.Writer, fetchProfile profileFetcher, listSessions authSessionLister, t statusTarget) error {
354		if t.token == "" {
355			if t.coreURL == "" {
356				fmt.Fprintln(w, "Not logged in.")
357			} else {
358				fmt.Fprintf(w, "Not logged in to %s\n", t.coreURL)
359			}
360			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
361			return nil
362		}
363	
364		profile, err := fetchProfile(ctx, t.coreURL, t.token)
365		if err != nil {
366			if isKeychainTokenRejected(err) {
367				fmt.Fprintf(w, "Login for %s is no longer valid.\n", t.coreURL)
368				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
369				return nil
370			}
371			return fmt.Errorf("validate token: %w", err)
372		}
373	
374		fmt.Fprintf(w, "Logged in to %s\n", t.coreURL)
375		writeProfileLines(w, profile)
376	
377		// ENTIRE_TOKEN mode: no stored context, keychain slot, or revocable
378		// session — the bearer is the env var itself. Name that and stop, rather
379		// than printing context/keychain/session lines that don't apply.
380		if t.envToken {
381			fmt.Fprintf(w, "  %-9s %s\n", "Token:", auth.EnvTokenVar+" environment variable")
382			return nil
383		}
384	
385		if t.activeContext != "" {
386			fmt.Fprintf(w, "  %-9s %s\n", "Context:", t.activeContext)
387		}
388		fmt.Fprintf(w, "  %-9s %s\n", "Token:", "stored in OS keychain")
389	
390		// Active sessions on this core. The token is already known good, so a
391		// listing failure is non-fatal — note it and carry on.
392		sessions, serr := listSessions(ctx, t.coreURL, t.token)
393		switch {
394		case serr != nil:
395			fmt.Fprintf(w, "\n(could not list active sessions: %v)\n", serr)
396		case len(sessions) > 0:
397			sortAuthSessionsByRecency(sessions)
398			fmt.Fprintf(w, "\nActive sessions (%d):\n", len(sessions))
399			renderAuthSessionsTable(w, newAuthTableStyles(w), sessions)
400			fmt.Fprintln(w, "\nRun 'entire logout' to end this session, or 'entire logout --everywhere' to end all of them.")
401		}
402	
403		if t.totalContexts > 1 {
404			fmt.Fprintln(w)
405			fmt.Fprintf(w, "%d login contexts saved; run 'entire auth contexts' to list or 'entire auth use <name>' to switch.\n", t.totalContexts)
406		}
407		return nil
408	}
