410	// writeProfileLines renders the user identity from GET /me as aligned
411	// label/value lines, omitting any field the server didn't populate.
412	func writeProfileLines(w io.Writer, p *authProfile) {
413		var parts []string
414		if p.DisplayName != "" {
415			parts = append(parts, p.DisplayName)
416		}
417		if p.Handle != "" {
418			parts = append(parts, "@"+p.Handle)
419		}
420		if p.Email != "" {
421			parts = append(parts, "<"+p.Email+">")
422		}
423		if len(parts) > 0 {
424			fmt.Fprintf(w, "  %-9s %s\n", "User:", strings.Join(parts, " "))
425		}
426		if p.Provider != "" {
427			identity := p.Provider
428			if p.ProviderUserID != "" {
429				identity += "/" + p.ProviderUserID
430			}
431			fmt.Fprintf(w, "  %-9s %s\n", "Identity:", identity)
432		}
433	}
