73	func runAPI(ctx context.Context, w, errW io.Writer, rawPath string, f *apiFlags) error {
74		insecure := applyInsecureHTTPAuth(f.insecureHTTP)
75	
76		client, err := resolveAPIClient(ctx, f.to, insecure)
77		if err != nil {
78			return err
79		}
80	
81		path, err := expandAPIPlaceholders(ctx, rawPath)
82		if err != nil {
83			return err
84		}
85		if err := validateAPIPath(path); err != nil {
86			return err
87		}
88	
89		fields, err := buildAPIFields(f.rawFields, f.typedFields)
90		if err != nil {
91			return err
92		}
93	
94		req, err := buildAPIRequestBody(path, f, fields)
95		if err != nil {
96			return err
97		}
98	
99		headers, err := parseAPIHeaders(f.headers)
100		if err != nil {
101			return err
102		}
103	
104		resp, err := client.Request(ctx, req.method, req.path, headers, req.body)
105		if err != nil {
106			return fmt.Errorf("%s %s: %w", req.method, req.path, err)
107		}
108		defer func() { _ = resp.Body.Close() }()
109	
110		return writeAPIResponse(w, errW, resp, f.include)
111	}
