113	// resolveAPIClient builds an authenticated client for the chosen backend. Both
114	// return an *api.Client whose base URL is the backend origin, so <path> is the
115	// full path (e.g. /api/v1/…) against that host.
116	func resolveAPIClient(ctx context.Context, to string, insecure bool) (*api.Client, error) {
117		switch strings.ToLower(strings.TrimSpace(to)) {
118		case "", "core":
119			target, err := resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
120			if err != nil {
121				return nil, err
122			}
123			if target.token == "" {
124				// Return a normal (non-silent) error so main.go prints the hint;
125				// a SilentError would exit non-zero with no explanation.
126				return nil, errors.New("not logged in: run 'entire login' to authenticate")
127			}
128			if !insecure && target.coreURL != "" {
129				if err := api.RequireSecureURL(target.coreURL); err != nil {
130					return nil, fmt.Errorf("control-plane URL check: %w", err)
131				}
132			}
133			return api.NewClientWithBaseURL(target.token, target.coreURL), nil
134		case "cell":
135			client, err := auth.NewEntireAPICellClient(ctx, insecure, nil)
136			if err != nil {
137				return nil, err //nolint:wrapcheck // NewEntireAPICellClient already returns contextual auth errors
138			}
139			return client, nil
140		default:
141			return nil, fmt.Errorf("unknown --to %q (use core or cell)", to)
142		}
143	}
